ids=set(by_id);accepted=set();active=set()
def visit(id):
 if id in accepted:return
 assert id not in active,'Dependency cycle'
 active.add(id)
 for dep in by_id[id]['dependencies']:
  assert dep in ids
  visit(dep)
 active.remove(id);accepted.add(id)
for id in ids:visit(id)
print(f'Validated {len(packages)} bounded work packages; dependency graph is acyclic.')
